from pathlib import Path
S=Path(__file__).parent
pages=[]
def shot(n,cls='hero'):return f'<img class="{cls}" src="../mockups/{n}.png">'
def notes(items):return '<div class="notes">'+''.join('<div><b>'+a+'</b><p>'+b+'</p></div>' for a,b in items)+'</div>'
def page(title,lead,body):
 k=len(pages)+1
 pages.append(f'<section class="page"><div class="kicker">VOIDCREW / EDITOR UI <span>{k:02d} / 12</span></div><h1>{title}</h1><p class="lead">{lead}</p>{body}<div class="pagefoot">Koncepció · 2026.11.14 · UI labels: English <span>Forrás: plan-v2.md + shots/ + public/ assets</span></div></section>')
page('Kevesebb keret. Több pálya.','Kompakt, játékon belüli level editor. Ajánlás: lebegő ikonok és visszahúzható panelek. A munkafelület a tér; a kezelőszervek a következő műveletet segítik.',shot('decorate-1440')+notes([('Művelet ≠ asset','Select / Dig / Height / Paint külön; egy asset választása Place módot aktivál.'),('Semleges üveg, arany fókusz','A sötét szürke mindkét világban használható. Az arany megtartja a játék karakterét; a kategóriaszínek külön a kijelölést jelzik.'),('Meglévő + tervezett','A mockupok statikus javaslatok. A további oldalak TERV jelölése a jelenlegi engine-hez képest új funkciót jelent; nincs forráskódmódosítás.')]))
page('Három felső vezérlési irány','Mindhárom ugyanazt a parancskészletet éri el. Az ajánlott megoldás nem foglalja el egy tömör fejléccel a teljes felső szélt.','<div class="alternatives">'+''.join(f'<article><div class="crop {v}">{shot("toolbar-"+v,"")}</div><div><h2>{t}</h2><p>{d}</p></div></article>' for v,t,d in [('a','A · Lebegő csoportok · AJÁNLOTT','Balra eszközök, jobbra fájl és nézet. A közép szabad; a helyek stabilak, az aktív eszköz mindig látszik. Illeszkedik a tulajdonosi irányhoz.'),('b','B · 40 px áttetsző sáv','Könnyen megtanulható és kiszámítható. A teljes szélességben állandó vizuális határ marad, ezért kevésbé légies.'),('c','C · Minimális sáv + Quick menu','A ritka parancsok radiális menüben. TERV: jobb kattintás nyitná, de ez ütközik a meglévő Orbit / Fill művelettel. Csak opcionális alternatíva; nem az ajánlott alap.')])+'</div>'+notes([('A láthatósága · TERV','Aktív eszköz + Save • mindig látható. A többi ikon 70% erősségű; hover / fókusz 100%, tooltip 500 ms után. A célterület nem tűnik el.'),('File és Place','File: New, Load, Save, Download, Shared Maps, Exit. Place: Door, Ladder, Bridge, Chance wall, Start, Exit, Restricted. Save as: Map Settings.'),('View és Debug','View: Textured, Faces, Wireframe, Normals, Depth. Debug külön fiók: Graphics, normal/metal/glow/AO, Stats, Play & Testing, Save to map. Save: devben lemez, máshol letöltés.')]))
page('Decorate / a tér marad a főszereplő','1440 × 860 · Select alapértelmezés. A fa csukva, a prop Inspectora nyitva. A láda a valódi crate1 diffuse-textúrájából készült illusztratív kompozit.',shot('decorate-1440')+notes([('Keskeny Inspector','256 px, 12 px perem; a kijelölést követi, üres kijelölésnél Map Settings. Becsukás / pin / auto-hide: TERV.'),('Prop megfogása · TERV','Arany size-doboz, egy yaw-gyűrű és magasságnyíl. A gyűrű 15° / 90° lépésekben forgat; a testen indított húzás a padlón mozgat.'),('Panel-életciklus · TERV','Kézi csukás módonként megmarad. Csak nem rögzített panel bújhat el viewport-műveletkor. Fókusz és mezőszerkesztés alatt nyitva marad; az oldalsó fül visszahozza.')]))
page('Build / alaprajz és tér egyszerre','1440 × 860 · Balra 40% nagy minimap, a fa elbújik. Jobbra 3D ellenőrzés és keskeny Inspector. M vagy a nagyítás ikon vált vissza Decorate módba.',shot('build-1440')+notes([('Meglévő alap','Nagy minimap, húzott blokk, Dig / Fill / Floor / Ceiling / Paint és gyors lapos előnézet már létezik. A Place menü mindvégig elérhető.'),('Új objektumréteg · TERV','Kategóriaszín + jelalak. Kattintás kijelöl, húzás cellát vált; NPC-útvonal, szemkapcsolók és nagy pályán pan / zoom a plan-v2 §10 szerint.'),('Rebuild-visszajelzés · TERV','Preview · full rebuild in 5 s az utolsó módosítástól számol; utána Rebuilding, végül Ready. A mechanika már megvan, a látható állapot új.')]))
page('Select / az Alt ideiglenes kitérő','TERV · Egy selection: { kind, index }. A Select a fő megoldás; Alt vagy tartott Q más eszközből ideiglenesen feloldja a kategóriavédelmet.',shot('global-select-1440')+notes([('Visszatérés és megszakítás','Paint → Alt le → Select → fény → Light Inspector. Alt fel → Paint; a kijelölés megmarad. Új javaslat: Escape a húzás előtti értékre állít vissza.'),('Találati sorrend','Legközelebbi találat; fedésnél NPC > item > prop > decal > light > surface. Place / Dig / Height nem fog meg véletlenül más fajtát. Alt: preventDefault, Q tartalék.'),('Megőrzött mozdulatok','Ctrl+drag másolat. Shift+drag ajtót visz más cellába; Snap külön kapcsoló. R / Shift+R: 90° / 15°. Ctrl+Z/Y, F és M támogatás a terv szerint; a mezőben gépelés nem mozgat objektumot.')]))
page('Asset-fa / választás, nem eszközrács','TERV · Valódi diffuse-bélyegképek, decalok, itemek és NPC idle-cellák. A fa a külön palettasorokat váltja ki; az Asset Manager megmarad.',shot('asset-tree-1440')+notes([('Keresés és világ','Név + fajta; opcionális Active category. Alapból az aktív világ assetInWorld szűrése: Void Fantasy / Void Crew. Üres eredmény: No results + Clear filters.'),('Szem és kategória','A szem az elhelyezett réteget rejti a viewportban és a minimapon; adatot nem töröl. A paletta böngészhető marad, rejtett példány a viewportból nem jelölhető. Bővítés: Lights, Doors, Markers.'),('Asset és felület','Kattintás → Place, dupla kattintás → Asset Manager. Textures kivétel: Paint, Wall / Floor / Ceiling / Default. Prop alcsoportok: 3D / Billboard / Pillar-Chamfer. A fa belül görgethető.')]))
page('Inspector / a fajtához tartozó mezők','Mezők: plan-v2 §6. Az angol UI-nevek fordított címkék, nem igazolt API-azonosítók. A mintaszámok illusztratívak; az until alert blokk itt szándékosan nyitott.',shot('inspectors')+notes([('Közös logika','Chance / with / without minden fajtánál azonos sorrendben. Hibás érték a mező mellett és a status message sorban is látszik. A változás a meglévő undo-folyamatot követi.'),('Ritka beállítások','Advanced alapból zárt: NPC until alert: dormant / fooled / arrive, frequency / max. Door: Key, Hack, Code, Locked chance, Says. Particle: Blow speed / direction / tilt.'),('Más fajták és Map','Decal: Surface, Position (px), Rotation, Action (terminal:<id>, lift, power). Item: Type, Count, Height. Map: Name, Size, Map, New / Save as, light density, relief, accent; Map Attributes / Lights / Texture Defaults / Variation & Mood.')]))
page('Ikonrendszer / rövid és következetes','Saját, egységes SVG-vonalikonok külön fájlokban. Az ikon mellett csak menüben és tooltipben szükséges szöveg; a kiválasztott eszköz neve az állapotsorban is megjelenik.',shot('icons')+notes([('Méretezés','24 × 24 px rajzrács; 1,6 px vonal; 20 px megjelenítés; 32 × 32 px desktop gomb; 44 × 44 px touch célterület.'),('Állapotok','Idle #d7e0ea; Active arany + kitöltés + keret; Focus 2 px világos külső gyűrű; Disabled 38% és indokló tooltip. Nem csak szín jelöl.'),('Elérhetőség · TERV','Angol accessible name, hover/focus tooltip, billentyűvel bejárható gombok. A menü Escape-re zár, fókusz visszatér a nyitó gombra; a viewport csak utána kapja vissza a billentyűket.')]))
page('Körvonalak / csak a létező szabadságfokok','TERV · A szín a 3D körvonalon, a minimap ikonon és a fa kategóriaszegélyén azonos. A fali prop a Prop kategóriaszínét örökli; az elemfajtát a jelalak is azonosítja.',shot('handles')+notes([('Olvasható kijelölés','Selected 2 px / 100% + 1 px sötét halo; hover 1 px / 45%. Csak az aktív elem kap fogantyút. A térbeli jelölés nem világít át a falon; minimapon továbbra is elérhető.'),('Találati terület · TERV','Látható pont 8 px; egér hit area 20 px, touch 44 px. Kamera-távolságtól független méret; ütköző fogantyúnál a közelebbi nyer.'),('Korlátok','Csak 3D prop kap egy yaw-gyűrűt. Decal sarokforgatás a felületen. NPC iránynyilai diszkrétek; a talpgyűrű nem forgató. Létra / híd: él / sáv, fogantyú nélkül.')]))
page('1024 × 768 / a panelek helyet adnak','Valódi 1024 × 768 renderelések. Fa alapból csukva, Inspector 232 px overlay; Buildben a nagy térkép 40%. Az állapotsor a napló legutóbbi üzenetét is megtartja.','<div class="twoshots">'+shot('decorate-1024','')+shot('build-1024','')+'</div><div class="status-demo"><div><b>Select</b> · Prop crate1 #12 · Cell 8, 6 <span>Snap: On · Save • · 60 FPS</span></div><div class="err">Editor: can\'t fill in the cell the party stands in <span>History ▴</span></div><div>Drag: move · Ctrl+drag: duplicate · R: 90° · Shift+R: 15°</div></div>'+notes([('Három sor · TERV','66 px: 3 × 18 px + 12 px tér. 1: tool / selection / hover. 2: legutóbbi üzenet. 3: kontextusos gyorsgombok. Hosszú sor csonkolva; a teljes szöveg History-ban és tooltipben.'),('Napló és Debug · TERV','History: 200 sor, visszagörgethető. Hiba piros ikon + szöveg; nem kizárólag eltűnő toast. Debug külön fiók, nem keveredik az elemmezőkkel.'),('Panelütközések · TERV','1024-en a fa nyitása becsukja a nem rögzített Inspectort. Menük egymást zárják; a panel a 3D fölött marad, belül görget. A fájlmenüben minden parancs elérhető.')]))
page('Touch / ugyanaz a modell, módosítók nélkül','TERV · Tablet / telefon landscape és portrait. Alsó 44 px-es eszközök, Inspector alsó lap, asset-fa oldalsó fiók. Buildben a térkép teljes képernyős.','<div class="mobilepair">'+shot('mobile-landscape','land')+shot('mobile-portrait','port')+'</div>'+notes([('Kijelölés','Select gomb elsődleges. Hosszú nyomás: 450 ms, 8 px mozgásküszöb (új javaslat). Duplicate és Rotate külön művelet; Alt/Ctrl nélkül. Kijelölés után az alsó lap nyílik.'),('Térkép és kamera','Egy ujj blokkjelölés, két ujj pan / pinch zoom. Viewport: egy ujj néz; Select alatt objektumról indulva húz. Kétujjas kameramozgás nem szerkeszt.'),('Lap és fiók','Portrait: összegzés vagy legfeljebb 55vh, belső scroll. Fa és Inspector felváltva nyílik. Safe-area padding; virtuális billentyűzetnél az aktív mező felgörgethető. Minden célterület ≥44 px.')]))
page('Specifikáció és megvalósítási sorrend','A plan-v2 funkcionális döntései megmaradnak; a felső sáv vizuális formája a tulajdonosi irány alapján A ikoncsoportra változik.','<div class="specgrid"><article><h2>UI tokenek</h2><div class="swatches">'+''.join(f'<i style="background:{c}"></i><span>{n} · {c}</span>' for n,c in [('Panel','#12161b'),('Game echo','#1a120a'),('Active','#c9a24a'),('Text','#e9edf1')])+'</div><p>Panel: 90% opacity, 12 px blur; toolbar: 82%. Border: white 14%; radius 8 px. Perem 12 px, belső tér 8-12 px, sor 32 px, gap 4-8 px.</p><p>Segoe UI: 13 px UI, 12 px mezőcímke, 11 px kiegészítő. Consolas: 11-12 px érték és status. Touch legalább 13 px. PDF: Arial.</p><h2>Minőségkapuk</h2><p>Mindkét világban olvasható; 1024-en nem ütköznek a gombok; fókusz és aktív eszköz látszik. Rejtés nem töröl; hiba visszakereshető.</p></article><article><h2>Függőségek · plan-v2 §13</h2><div class="road"><b>1 · Layout + status + Debug</b><i>↓</i><b>2 · Inspector + Map Settings</b><i>↓</i><b>3 · selection + Select + Alt/Q</b><i>↓</i><b>4 · Outlines → 5 · Handles</b><i>↘</i><b>6 · Asset tree (1 után is)</b><i>↓</i><b>7 · 2D ikonréteg (3 után)</b><i>↓</i><b>8 · Touch (2 + 6 után)</b></div></article><article><h2>Mi új, mi kész?</h2><p><b>Meglévő a terv szerint:</b> kategóriánkénti drag, Ctrl+C/V, nagy minimap + blokk, 5 s rebuild, Asset Manager, nézetmódok.</p><p><b>TERV:</b> egységes selection, Select + Alt, kategória-körvonalak, fogantyúk, fa/kereső/szem-bővítés, 2D ikonréteg, status/history, touch és panel-átrendezés.</p><p><b>Új design-részlet:</b> pin/auto-hide szabály, Escape rollback, touch küszöbök, hit area és paletta; prototípusban validálandó.</p><p><b>Később:</b> többes objektumkijelölés és 3D Topdown (9. lépés). C radiális menü opcionális.</p><h2>Átadás</h2><p>HTML/CSS/SVG forrás + PNG-k. Valódi shots/ háttér, public/ diffuse és CSS-sel kivágott NPC. A képek tervezési kompozitok, nem új 3D renderelések.</p></article></div>')
(S/'document.html').write_text('<!doctype html><html lang="hu"><meta charset="utf-8"><title>voidcrew / Editor UI</title><link rel="stylesheet" href="document.css"><body>'+''.join(pages)+'</body></html>',encoding='utf-8')
print(len(pages),'pages')
